+                cbid == API_CUDA_cuLaunchKernel) {
+                cuLaunchKernel_params* p = (cuLaunchKernel_params*)params;
+                uint64_t num_threads = p->gridDimX * p->gridDimY * p->gridDimZ * p->blockDimX * p->blockDimY * p->blockDimZ;
