+                    printf(
+                    "Entering: CTX 0x%016lx - LAUNCH "
+                    "Kernel name %s - grid launch id %ld - grid size %d,%d,%d "
+                    "- block size %d,%d,%d - cuda stream "
+                    "id %ld - threads: %ld\n",
+                    (uint64_t)ctx, nvbit_get_func_name(ctx, p->f, mangled), grid_launch_id, p->gridDimX,
