+/*
+ * cuFuzz Sample Application
+ * Simple vector operation kernel with an intentional OOB bug for testing.
+ *
+ * Author: Mohamed Tarek (mtarek@nvidia.com)
+ */
+
+#include <stdio.h>
+
+// For the CUDA runtime routines (prefixed with "cuda_")
+#include <cuda_runtime.h>
+
+/**
+ * CUDA Kernel Device code
+ */
+__global__ void vectorOp(const float *A, const float *B, float *C,
+                          int numElements, int select) {
+  int i = blockDim.x * blockIdx.x + threadIdx.x;
+
+  if (i < numElements) {
+	  if (select == 1)
+      C[i] = A[i] + B[i];     // Add 
+    else if (select == 2)
+      C[i] = A[i] + 2*B[i];   // Double B and Add
+      //C[i] = A[i] + B[1003] + 10.0f;
+    else if (select == 3)
+      C[i] = 2*A[i] + B[i];   // Double A and Add
+    else if (select == 4)
+      C[i] = A[i] - B[i];     // Subtract 
+    else if (select == 5)
+      C[i] = 2*A[i] - B[i];   // Double A and subtract
+    else if (select == 6)
+      C[i] = A[i] + B[i+1000];// Access OOB memory!
+    else if (select == 7)
+      C[i] = A[i] - 2*B[i];   // Double B and subtract
+    else 
+      C[i] = A[i] + B[i];     // Add    
+      
+  }
+}
+
+/**
+ * Host main routine
+ */
+int main(int argc, char *argv[]) {
+  // Error code to check return values for CUDA calls
+  cudaError_t err = cudaSuccess;
+
+  // Print the vector length to be used, and compute its size
+  int numElements = 1000;
+
+  if (argc != 2) {
+      printf("Usage: %s <input_file>\n", argv[0]);
+      return 1;
+  }
+
+  int select = 0;
+  FILE *file = fopen(argv[1], "r");
+  if (file == NULL) {
+      printf("Error opening file %s.\n", argv[1]);
+      return 1;
+  }
+  fscanf(file, "%d", &select);
+  fclose(file);
+
+  printf("\nVectorOp select: %d \n", select);
+
+  size_t size = numElements * sizeof(float);
+  printf("Num of elements: %d \n", numElements);
+
+  // Allocate the host input vector A
+  float *h_A = (float *)malloc(size);
+
+  // Allocate the host input vector B
+  float *h_B = (float *)malloc(size);
+
+  // Allocate the host output vector C
+  float *h_C = (float *)malloc(size);
+
+  // Verify that allocations succeeded
+  if (h_A == NULL || h_B == NULL || h_C == NULL) {
+    fprintf(stderr, "Failed to allocate host vectors!\n");
+    exit(EXIT_FAILURE);
+  }
+
+  // Initialize the host input vectors
+  for (int i = 0; i < numElements; ++i) {
+    h_A[i] = rand() / (float)RAND_MAX;
+    h_B[i] = rand() / (float)RAND_MAX;
+  }
+
+  // Allocate the device input vector A
+  float *d_A = NULL;
+  err = cudaMalloc((void **)&d_A, size);
+
+  if (err != cudaSuccess) {
+    fprintf(stderr, "Failed to allocate device vector A (error code %s)!\n",
+            cudaGetErrorString(err));
+    exit(EXIT_FAILURE);
+  }
+
+  // Allocate the device input vector B
+  float *d_B = NULL;
+  err = cudaMalloc((void **)&d_B, size);
+
+  if (err != cudaSuccess) {
+    fprintf(stderr, "Failed to allocate device vector B (error code %s)!\n",
+            cudaGetErrorString(err));
+    exit(EXIT_FAILURE);
+  }
+
+  // Allocate the device output vector C
+  float *d_C = NULL;
+  err = cudaMalloc((void **)&d_C, size);
+
+  if (err != cudaSuccess) {
+    fprintf(stderr, "Failed to allocate device vector C (error code %s)!\n",
+            cudaGetErrorString(err));
+    exit(EXIT_FAILURE);
+  }
+
+  // Copy the host input vectors A and B in host memory to the device input
+  // vectors in
+  // device memory
+  printf("Copy input data from the host memory to the CUDA device\n");
+  err = cudaMemcpy(d_A, h_A, size, cudaMemcpyHostToDevice);
+
+  if (err != cudaSuccess) {
+    fprintf(stderr,
+            "Failed to copy vector A from host to device (error code %s)!\n",
+            cudaGetErrorString(err));
+    exit(EXIT_FAILURE);
+  }
+
+  err = cudaMemcpy(d_B, h_B, size, cudaMemcpyHostToDevice);
+
+  if (err != cudaSuccess) {
+    fprintf(stderr,
+            "Failed to copy vector B from host to device (error code %s)!\n",
+            cudaGetErrorString(err));
+    exit(EXIT_FAILURE);
+  }
+
+  // Launch the Vector Add CUDA Kernel
+  int threadsPerBlock = 256;
+  int blocksPerGrid = (numElements + threadsPerBlock - 1) / threadsPerBlock;
+  printf("CUDA kernel launch with %d blocks of %d threads\n", blocksPerGrid,
+         threadsPerBlock);
+  vectorOp<<<blocksPerGrid, threadsPerBlock>>>(d_A, d_B, d_C, numElements, select);
+  err = cudaGetLastError();
+
+  if (err != cudaSuccess) {
+    fprintf(stderr, "Failed to launch vectorOp kernel (error code %s)!\n",
+            cudaGetErrorString(err));
+    exit(EXIT_FAILURE);
+  }
+
+  // Copy the device result vector in device memory to the host result vector
+  // in host memory.
+  printf("Copy output data from the CUDA device to the host memory\n");
+  err = cudaMemcpy(h_C, d_C, size, cudaMemcpyDeviceToHost);
+
+  if (err != cudaSuccess) {
+    fprintf(stderr,
+            "Failed to copy vector C from device to host (error code %s)!\n",
+            cudaGetErrorString(err));
+    exit(EXIT_FAILURE);
+  }
+
+  printf("Test PASSED\n");
+
+  // Free device global memory
+  err = cudaFree(d_A);
+
+  if (err != cudaSuccess) {
+    fprintf(stderr, "Failed to free device vector A (error code %s)!\n",
+            cudaGetErrorString(err));
+    exit(EXIT_FAILURE);
+  }
+
+  err = cudaFree(d_B);
+
+  if (err != cudaSuccess) {
+    fprintf(stderr, "Failed to free device vector B (error code %s)!\n",
+            cudaGetErrorString(err));
+    exit(EXIT_FAILURE);
+  }
+
+  err = cudaFree(d_C);
+
+  if (err != cudaSuccess) {
+    fprintf(stderr, "Failed to free device vector C (error code %s)!\n",
+            cudaGetErrorString(err));
+    exit(EXIT_FAILURE);
+  }
+
+  // Free host memory
+  free(h_A);
+  free(h_B);
+  free(h_C);
+
+  printf("Done\n");
+  return 0;
+}

